program.compute:
options = read('/input/options')
result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for choice in combinations(options, k):
        ids = [record['id'] for record in choice]
        if valid(ids):
            result = ids
            break
    if len(result) > 0:
        break

program.effects:
if exists('/output/selection'):
    existing = read('/output/selection')
    if valid(existing):
        result = existing
    else:
        result = []
else:
    if valid(result):
        write('/output/selection', result)
if len(result) > 0 and status('report') == 'not_sent':
    send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')

